package com.qrid.servlet;
import com.qrid.config.Database;import com.qrid.util.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;import java.sql.*;
@WebServlet("/contact") public class ContactServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{String n=Validation.text(r.getParameter("name"),100),e=Validation.text(r.getParameter("email"),120),sub=Validation.text(r.getParameter("subject"),160),m=Validation.text(r.getParameter("message"),2000);if(n.length()<2||!Validation.email(e)||m.length()<10)throw new IllegalArgumentException("Enter valid contact details and message.");try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)")){p.setString(1,n);p.setString(2,e);p.setString(3,sub);p.setString(4,m);p.executeUpdate();}Flash.set(r,"success","Your message was received.");}catch(Exception ex){Flash.set(r,"danger",ex.getMessage());}s.sendRedirect(r.getContextPath()+"/contact.jsp");}}
